void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85;  // slightly more aggressive reduction to trigger rephasing more frequently
    rephase_limit += 4096;  // smaller increment to allow more frequent rephasing cycles
    // Update saved phases based on current trail state
    for (int i = 1; i <= vars; i++) {
        if (value[i] != 0) {
            saved[i] = value[i];  // use current assignment as phase
        } else if (local_best[i] != 0) {
            saved[i] = local_best[i];  // fallback to local best
        } else {
            saved[i] = rand() % 2 ? 1 : -1;  // random fallback
        }
    }
}
